<?php $isProjectFavorite=(bool)Db::one("SELECT entity_id FROM work_favorites WHERE workspace_id=? AND entity='project' AND entity_id=?",[$workspace['id'],$project['id']]);$workPath='/work/project/'.$project['id'];$workQuery=static function(array $change=[])use($listing,$layout,$month):string{$filters=array_diff_key($listing['filters'],array_flip(['range_from','range_to','range_mode']));$values=array_merge($filters,['layout'=>$layout,'month'=>$month],$change);return http_build_query(array_filter($values,fn($value)=>$value!==''&&$value!==null));}; ?>
<div class="topline"><a href="/work?workspace=<?= e($workspace['id']) ?>"><?= e($workspace['name']) ?></a><span><?= e($project['identifier']) ?> · <?= e(ucfirst($project['kind'])) ?></span></div><header class="page-header work-project-header"><div><span class="website-kicker">PROJECT WORKSPACE</span><h1><?= e($project['name']) ?></h1><p class="muted"><?= e(mb_strimwidth($project['description'],0,200,'…')) ?></p></div><div class="hero-actions"><?php if($project['status']!=='archived'): ?><a class="btn" href="<?= $workPath ?>#work-new-issue">+ Work item</a><?php endif; ?><form method="post" action="/work/workspace/<?= e($workspace['id']) ?>/favorite"><?= csrf_field() ?><input type="hidden" name="entity" value="project"><input type="hidden" name="entity_id" value="<?= e($project['id']) ?>"><input type="hidden" name="on" value="<?= $isProjectFavorite?'0':'1' ?>"><button class="secondary"><?= $isProjectFavorite?'Remove favourite':'Favourite project' ?></button></form></div></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<?php if($project['status']==='archived'): ?><section class="card"><h2>This project is archived.</h2><p class="muted">Its work items, pages and history are preserved.</p><form method="post" action="<?= $workPath ?>/archive"><?= csrf_field() ?><input type="hidden" name="restore" value="1"><button>Restore project</button></form></section><?php endif; ?>
<nav class="tabs work-tabs" aria-label="Project pages"><?php foreach(['issues'=>'Work items','cycles'=>'Cycles','modules'=>'Modules','releases'=>'Releases','pages'=>'Pages','views'=>'Views','analytics'=>'Analytics','activity'=>'Activity','settings'=>'Settings'] as $key=>$label): ?><a href="<?= $workPath ?>?tab=<?= $key ?>" <?= $tab===$key?'class="selected" aria-current="page"':'' ?>><?= $label ?></a><?php endforeach; ?></nav>
<?php if($tab==='issues'): ?>
<div class="work-issue-controls"><nav class="work-layout-switch" aria-label="Work-item layout"><?php foreach(WorkService::LAYOUTS as $value=>$label): ?><a href="<?= $workPath ?>?<?= e($workQuery(['layout'=>$value,'page'=>1])) ?>" <?= $layout===$value?'class="selected" aria-current="page"':'' ?>><?= $label ?></a><?php endforeach; ?></nav><div class="hero-actions"><a href="<?= $workPath ?>/export.csv?<?= e($workQuery()) ?>" hx-boost="false">Export CSV</a><a href="<?= $workPath ?>?tab=views">Save a view</a></div></div>
<section class="card work-filter-card"><form class="work-filters" method="get" action="<?= $workPath ?>"><input type="hidden" name="layout" value="<?= e($layout) ?>"><label class="work-search">Search<input name="q" type="search" maxlength="200" value="<?= e($listing['filters']['q']) ?>" placeholder="Title, description or <?= e($project['identifier']) ?>-1"></label><label>Show<select name="scope"><?php foreach(['active'=>'Active items','mine'=>'Assigned to me','overdue'=>'Overdue','intake'=>'Intake','rejected'=>'Rejected requests','archived'=>'Archived','trash'=>'Trash'] as $value=>$label): ?><option value="<?= $value ?>" <?= $listing['filters']['scope']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>State<select name="state"><option value="">All states</option><?php foreach($states as $state): ?><option value="<?= e($state['id']) ?>" <?= $listing['filters']['state']===$state['id']?'selected':'' ?>><?= e($state['name']) ?></option><?php endforeach; ?></select></label><label>Priority<select name="priority"><option value="">All priorities</option><?php foreach(WorkService::PRIORITIES as $key=>$label): ?><option value="<?= $key ?>" <?= $listing['filters']['priority']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><details class="work-more-filters"><summary>More filters</summary><div class="form-grid"><label>Type<select name="issue_type"><option value="">All types</option><?php foreach(WorkService::TYPES as $value=>$label): ?><option value="<?= $value ?>" <?= $listing['filters']['issue_type']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Release<select name="release"><option value="">All releases</option><?php foreach($releases as $release): ?><option value="<?= e($release['id']) ?>" <?= $listing['filters']['release']===$release['id']?'selected':'' ?>><?= e($release['name']) ?></option><?php endforeach; ?></select></label><label>Assignee<select name="assignee"><option value="">All people</option><?php foreach($people as $person): ?><option value="<?= e($person['id']) ?>" <?= $listing['filters']['assignee']===$person['id']?'selected':'' ?>><?= e($person['name']) ?></option><?php endforeach; ?></select></label><label>Label<select name="label"><option value="">All labels</option><?php foreach($labels as $label): ?><option value="<?= e($label['id']) ?>" <?= $listing['filters']['label']===$label['id']?'selected':'' ?>><?= e($label['name']) ?></option><?php endforeach; ?></select></label><label>Cycle<select name="cycle"><option value="">All cycles</option><?php foreach($cycles as $cycle): ?><option value="<?= e($cycle['id']) ?>" <?= $listing['filters']['cycle']===$cycle['id']?'selected':'' ?>><?= e($cycle['name']) ?></option><?php endforeach; ?></select></label><label>Module<select name="module"><option value="">All modules</option><?php foreach($modules as $module): ?><option value="<?= e($module['id']) ?>" <?= $listing['filters']['module']===$module['id']?'selected':'' ?>><?= e($module['name']) ?></option><?php endforeach; ?></select></label><label>Order<select name="order"><?php foreach(['manual'=>'Workflow order','priority'=>'Priority','updated'=>'Recently updated','due'=>'Due date'] as $value=>$label): ?><option value="<?= $value ?>" <?= $listing['filters']['order']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label></div></details><button class="secondary">Apply filters</button><a href="<?= $workPath ?>?layout=<?= e($layout) ?>">Clear</a></form></section>
<div class="section-heading work-result-heading"><p class="muted"><?= $listing['total'] ?> matching <?= $listing['total']===1?'work item':'work items' ?><?= $savedView?' · View: '.e($savedView['name']):'' ?></p><span class="badge">Saved on this laptop</span></div>
<?php require __DIR__.'/issue-layouts.php'; ?>
<?php if($listing['pages']>1): ?><nav class="studio-pagination" aria-label="Work-item pages"><?php if($listing['page']>1): ?><a href="<?= $workPath ?>?<?= e($workQuery(['page'=>$listing['page']-1])) ?>">← Previous</a><?php endif; ?><span>Page <?= $listing['page'] ?> of <?= $listing['pages'] ?></span><?php if($listing['page']<$listing['pages']): ?><a href="<?= $workPath ?>?<?= e($workQuery(['page'=>$listing['page']+1])) ?>">Next →</a><?php endif; ?></nav><?php endif; ?>
<?php if($project['status']!=='archived'): ?><details class="card work-new-issue" id="work-new-issue" <?= !$listing['total']?'open':'' ?>><summary><strong>+ Create work item</strong></summary><?php $editIssue=null;$issueFormAction=$workPath.'/issues';require __DIR__.'/issue-form.php'; ?></details><?php endif; ?>
<?php elseif(in_array($tab,['cycles','modules'],true)): require __DIR__.'/groupings.php';
elseif($tab==='releases'): require __DIR__.'/releases.php';
elseif($tab==='pages'): require __DIR__.'/pages.php';
elseif($tab==='views'): require __DIR__.'/views.php';
elseif($tab==='analytics'): require __DIR__.'/analytics.php';
elseif($tab==='settings'): require __DIR__.'/settings.php';
elseif($tab==='activity'): ?><section class="card"><h2>Project activity</h2><?php $events=WorkService::activity((int)$project['id']);if(!$events): ?><p class="muted">No activity recorded yet.</p><?php else:foreach($events as $event): ?><article class="studio-activity"><span class="studio-activity-mark"><?= icon('check') ?></span><div><strong><?= e(str_replace('.',' · ',$event['event'])) ?></strong><p><?= e($event['actor_name']) ?><?= $event['detail']!==''?' · '.e(mb_strimwidth($event['detail'],0,180,'…')):'' ?></p></div><time><?= e($event['created_at']) ?></time></article><?php endforeach;endif; ?></section><?php endif; ?>
